css:
.bd2-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.bd2-stage canvas { touch-action: none; cursor: grab; }
.bd2-stage canvas.holding { cursor: grabbing; }
.bd2-table { width: 100%; border-collapse: collapse; font-size: 16px; }
.bd2-table th, .bd2-table td { border-bottom: 1px solid #d5dae2; padding: 3px 6px; text-align: left; vertical-align: top; }
.bd2-table th { font-size: 14px; color: #5a6475; }
.bd2-table tr.on td { background: #fff3c2; font-weight: 800; }
.bd2-out { margin: 0; font-size: 18px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 5.6em; }
.bd2-ex { display: block; margin-top: 4px; font-weight: 800; color: #8a5a00; }

